import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        all_binary = True
        for i in range(n):
            if not all_binary:
                break
            row = adj[i]
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
        if all_binary:
            is_matrix = True

    # Build adjacency list from input
    if is_matrix:
        graph = []
        for i in range(n):
            neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
            graph.append(neighbors)
    else:
        # Ensure adjacency list is properly formatted
        graph = []
        for i in range(n):
            if i < len(adj):
                graph.append(list(adj[i]))
            else:
                graph.append([])

    # Trivial cases
    if n == 1:
        return [0]

    # Check for edgeless graph
    has_edge = False
    for i in range(n):
        if graph[i]:
            has_edge = True
            break
    if not has_edge:
        return [0] * n

    # Check for complete graph
    is_complete = True
    for i in range(n):
        if len(graph[i]) != n - 1:
            is_complete = False
            break
    if is_complete:
        return list(range(n))

    # Compute degeneracy ordering (smallest-last) for initial bound
    def degeneracy_ordering():
        deg = [len(graph[i]) for i in range(n)]
        removed = [False] * n
        order = []
        buckets = [[] for _ in range(n)]
        for i in range(n):
            d = deg[i]
            if d < n:
                buckets[d].append(i)
        ptr = 0
        for _ in range(n):
            while ptr < n and not buckets[ptr]:
                ptr += 1
            if ptr >= n:
                break
            v = buckets[ptr].pop()
            if removed[v]:
                continue
            removed[v] = True
            order.append(v)
            for u in graph[v]:
                if not removed[u]:
                    d_u = deg[u]
                    deg[u] = d_u - 1
                    if deg[u] < n:
                        buckets[deg[u]].append(u)
        return order[::-1]  # reverse to get smallest-last order

    order = degeneracy_ordering()
    # Welsh-Powell: greedy on degeneracy ordering
    color = [-1] * n
    for v in order:
        used = [False] * (n + 1)
        for u in graph[v]:
            if color[u] != -1:
                used[color[u]] = True
        c = 0
        while c <= n and used[c]:
            c += 1
        color[v] = c
    k = max(color) + 1 if n > 0 else 0

    # Try to improve using Kempe chain swaps
    improved = True
    # Limit iterations to ensure time budget
    for _ in range(10):  # sufficient for n <= 100
        if not improved:
            break
        improved = False
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k - 1, -1, -1):
            # Build list of vertices with target_color
            verts = [v for v in range(n) if color[v] == target_color]
            if not verts:
                continue
            # Try to recolor each vertex in this class
            for v in verts:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in graph[v]:
                    if color[u] != -1:
                        neighbor_colors.add(color[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        color[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chain swaps
                for c in range(target_color):
                    # If v already has color c from direct reassignment attempt, skip
                    if color[v] == c:
                        continue
                    # Check if v is adjacent to any vertex of color c
                    adj_to_c = False
                    for u in graph[v]:
                        if color[u] == c:
                            adj_to_c = True
                            break
                    if adj_to_c:
                        continue
                    # Build the (target_color, c) Kempe chain containing v
                    stack = [v]
                    visited = [False] * n
                    visited[v] = True
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for u in graph[node]:
                            if not visited[u] and (color[u] == target_color or color[u] == c):
                                visited[u] = True
                                stack.append(u)
                    # Check if any neighbor of v in the component has color c
                    has_c_neighbor = False
                    for u in component:
                        for w in graph[u]:
                            if color[w] == c:
                                has_c_neighbor = True
                                break
                        if has_c_neighbor:
                            break
                    if not has_c_neighbor:
                        # Swap colors in the component
                        for node in component:
                            if color[node] == target_color:
                                color[node] = c
                            elif color[node] == c:
                                color[node] = target_color
                        improved = True
                        break
                if improved:
                    break
            if improved:
                break
        # Recompute k after potential improvements
        k = max(color) + 1 if n > 0 else 0

    return color

