def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix if square and binary entries (0/1)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for i in range(n):
            for j in range(n):
                val = adj[i][j]
                if val != 0 and val != 1:
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and degree array
    neighbors = [[] for _ in range(n)]
    degree = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
        degree = [len(neighbors[i]) for i in range(n)]
    else:
        for i in range(n):
            neighbors[i] = list(adj[i])  # copy to avoid side effects
        degree = [len(neighbors[i]) for i in range(n)]

    # Try Welsh-Powell (degree ordering) for a quick upper bound
    order_wp = sorted(range(n), key=lambda x: (-degree[x], x))
    colors_wp = [-1] * n
    max_color_wp = 0
    for v in order_wp:
        used = [False] * (n + 1)
        for u in neighbors[v]:
            if colors_wp[u] != -1:
                used[colors_wp[u]] = True
        c = 0
        while used[c]:
            c += 1
        colors_wp[v] = c
        if c > max_color_wp:
            max_color_wp = c
    wp_colors = max_color_wp + 1

    # DSATUR heuristic
    colors = [-1] * n
    saturation = [set() for _ in range(n)]
    uncolored_set = set(range(n))

    for _ in range(n):
        if not uncolored_set:
            break
        # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then index
        v = -1
        max_sat = -1
        max_deg_uncolored = -1
        for u in uncolored_set:
            sat_u = len(saturation[u])
            if sat_u > max_sat:
                max_sat = sat_u
                max_deg_uncolored = sum(1 for w in neighbors[u] if w in uncolored_set)
                v = u
            elif sat_u == max_sat:
                deg_uncolored = sum(1 for w in neighbors[u] if w in uncolored_set)
                if deg_uncolored > max_deg_uncolored:
                    max_deg_uncolored = deg_uncolored
                    v = u
                elif deg_uncolored == max_deg_uncolored and u < v:
                    v = u
        # Assign smallest available color
        used = [False] * (n + 1)
        for u in neighbors[v]:
            if colors[u] != -1:
                used[colors[u]] = True
        c = 0
        while used[c]:
            c += 1
        colors[v] = c
        uncolored_set.remove(v)
        # Update saturation of uncolored neighbors
        for u in neighbors[v]:
            if u in uncolored_set:
                saturation[u].add(c)

    dsatur_colors = max(colors) + 1 if n > 0 else 0

    # If DSATUR matches Welsh-Powell upper bound, it might be optimal; try to improve
    best_colors = colors[:]
    best_k = dsatur_colors

    # Try RLF (Recursive Largest First) independent set extraction
    def rlf_coloring():
        nonlocal best_colors, best_k
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = []
            # Start with vertex of max degree in uncolored subgraph
            v = -1
            max_deg = -1
            for u in uncolored:
                deg = sum(1 for w in neighbors[u] if w in uncolored)
                if deg > max_deg:
                    max_deg = deg
                    v = u
                elif deg == max_deg and u < v:
                    v = u
            if v == -1:
                break  # should not happen
            S.append(v)
            # Partition remaining uncolored into U (not adjacent to S) and W (adjacent to S)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if any(w in S for w in neighbors[u]):
                    W.add(u)
                else:
                    U.add(u)
            # Grow independent set S
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u_star = -1
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
                    nw = sum(1 for w in neighbors[u] if w in W)
                    if nw > max_nw:
                        max_nw = nw
                        min_deg_u = sum(1 for w in neighbors[u] if w in U)
                        u_star = u
                    elif nw == max_nw:
                        deg_u = sum(1 for w in neighbors[u] if w in U)
                        if deg_u < min_deg_u:
                            min_deg_u = deg_u
                            u_star = u
                        elif deg_u == min_deg_u and u < u_star:
                            u_star = u
                if u_star == -1:
                    break
                S.append(u_star)
                U.remove(u_star)
                # Move neighbors of u_star in U to W
                for w in neighbors[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for u in S:
                color[u] = c
                if u in uncolored:
                    uncolored.remove(u)
            c += 1
        k = max(color) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_colors = color[:]

    rlf_coloring()

    # Kempe chain local search to eliminate the last color class if possible
    def kempe_reduce(colors_list, k_val):
        if k_val <= 1:
            return colors_list, k_val
        # Work on a copy
        col = colors_list[:]
        changed = True
        # Try to reduce from k_val-1 down as much as possible
        while changed and k_val > 1:
            changed = False
            target_color = k_val - 1
            # Get vertices with target_color
            verts = [v for v in range(n) if col[v] == target_color]
            # Try to recolor each vertex to a lower color
            for v in verts:
                # Check direct move to any lower color
                neighbor_colors = set()
                for u in neighbors[v]:
                    if col[u] != -1:
                        neighbor_colors.add(col[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        col[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart scan as colors changed
                # Try Kempe chains for each lower color
                for c in range(target_color):
                    if c in neighbor_colors:
                        continue  # skip if neighbor has color c, swapping may not help directly
                    # We consider swapping colors target_color and c in the component containing v
                    # Only if v is not adjacent to any c-colored vertex (already checked)
                    # Build the Kempe chain component of v for colors {target_color, c}
                    stack = [v]
                    visited = set([v])
                    comp = set()
                    while stack:
                        node = stack.pop()
                        comp.add(node)
                        for u in neighbors[node]:
                            if col[u] == target_color or col[u] == c:
                                if u not in visited:
                                    visited.add(u)
                                    stack.append(u)
                    # Check if any neighbor of v in the component has color c? Actually, we know v has no neighbor with color c (from above)
                    # But after swap, we must ensure no conflict: vertices in comp that are target_color become c, and vice versa.
                    # Since v is target_color and has no neighbor with color c, after swap v becomes c and still no conflict.
                    # For other vertices in comp: if a vertex u in comp is target_color, its neighbors outside comp are not c (because if they were, they'd be in comp via the edge? Actually, not necessarily: if a neighbor is c and not in comp, then u (target_color) adjacent to c-colored vertex -> after swap u becomes c and adjacent to c -> conflict.
                    # So we must ensure that no vertex in the comp that is target_color has a neighbor outside the comp with color c.
                    safe = True
                    for u in comp:
                        if col[u] == target_color:
                            for w in neighbors[u]:
                                if w not in comp and col[w] == c:
                                    safe = False
                                    break
                            if not safe:
                                break
                    if safe:
                        # Perform swap
                        for u in comp:
                            if col[u] == target_color:
                                col[u] = c
                            elif col[u] == c:
                                col[u] = target_color
                        changed = True
                        break  # break color loop
                if changed:
                    break  # break vertex loop
            if changed:
                # After a successful recolor, check if target_color class is empty
                if any(col[v] == target_color for v in range(n)):
                    k_val = max(col) + 1  # recalc k
                else:
                    k_val -= 1
        return col, k_val

    # Apply Kempe reduction on the best found so far
    final_colors, final_k = kempe_reduce(best_colors, best_k)
    if final_k < best_k:
        best_k = final_k
        best_colors = final_colors

    return best_colors

