def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)

    # Detect if input is adjacency matrix (square and binary)
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor sets from adjacency representation
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        # Treat as adjacency list
        for i in range(n):
            # Ensure we have a list of integers
            if isinstance(adj[i], list):
                for j in adj[i]:
                    if 0 <= j < n:
                        neighbors[i].add(j)

    # Handle trivial cases
    if n == 1:
        return [0]

    # Check if graph has no edges
    has_edges = any(len(neighbors[i]) > 0 for i in range(n))
    if not has_edges:
        return [0] * n

    # DSATUR implementation
    color = [-1] * n          # -1 indicates uncolored
    saturation = [0] * n      # saturation degree (number of distinct colors in neighbors)
    # For tie-breaking: degree in the uncolored subgraph
    uncolored_deg = [len(neighbors[i]) for i in range(n)]
    uncolored_count = n

    # We'll maintain a list of uncolored vertices for efficiency
    uncolored = set(range(n))

    # Main coloring loop
    while uncolored:
        # Select vertex with maximum saturation degree
        # Tie-break: max uncolored degree, then random
        candidates = []
        max_sat = -1
        for v in uncolored:
            if saturation[v] > max_sat:
                max_sat = saturation[v]
                candidates = [v]
            elif saturation[v] == max_sat:
                candidates.append(v)

        if len(candidates) == 1:
            v = candidates[0]
        else:
            # Tie-break by uncolored degree (descending)
            max_deg = -1
            deg_candidates = []
            for v in candidates:
                deg = uncolored_deg[v]
                if deg > max_deg:
                    max_deg = deg
                    deg_candidates = [v]
                elif deg == max_deg:
                    deg_candidates.append(v)
            if len(deg_candidates) == 1:
                v = deg_candidates[0]
            else:
                # Final tie-break: random choice
                v = random.choice(deg_candidates)

        # Find smallest available color for v
        used_colors = set()
        for u in neighbors[v]:
            if color[u] != -1:
                used_colors.add(color[u])
        c = 0
        while c in used_colors:
            c += 1
        color[v] = c

        # Remove v from uncolored and update structures
        uncolored.remove(v)
        uncolored_count -= 1

        # Update saturation and uncolored degree for neighbors
        for u in neighbors[v]:
            if color[u] == -1:  # u is uncolored
                # Update saturation: if color c is new in u's neighborhood
                # We can't easily track distinct colors without more state, so we recalc saturation for u
                # But to stay efficient, we note that adding color c to v's color may increase saturation of u
                # only if none of u's other colored neighbors have color c.
                # However, for simplicity and correctness, we recalc saturation for u from scratch.
                # Since n <= 100, and each vertex has at most n neighbors, this is O(n^2) overall.
                neighbor_colors = set()
                for w in neighbors[u]:
                    if color[w] != -1:
                        neighbor_colors.add(color[w])
                saturation[u] = len(neighbor_colors)
                # Update uncolored degree: lose one uncolored neighbor (v)
                uncolored_deg[u] -= 1

    # Now we have a coloring from DSATUR, try to improve it by eliminating the last color class
    max_color = max(color) if n > 0 else -1
    if max_color < 0:  # no vertices
        return color

    # Try to reduce the number of colors by eliminating the highest color class
    # We'll attempt to reassign vertices of color max_color to lower colors
    improved = True
    while improved and max_color > 0:
        improved = False
        # Get vertices with the current highest color
        highest_color_vertices = [v for v in range(n) if color[v] == max_color]
        if not highest_color_vertices:
            max_color -= 1
            continue

        # Try to recolor each vertex in highest_color_vertices to a lower color
        for v in highest_color_vertices:
            # Try all lower colors in order
            for c in range(max_color):
                # Check if color c is available for v (no neighbor has color c)
                conflict = False
                for u in neighbors[v]:
                    if color[u] == c:
                        conflict = True
                        break
                if not conflict:
                    # Recolor v to c
                    color[v] = c
                    improved = True
                    # After recoloring, we may be able to reduce max_color further
                    # Break to restart the check for the new max_color
                    break
            if improved:
                break

        # If we made progress, check if the highest color class is now empty
        if improved:
            # Recompute max_color
            max_color = max(color) if n > 0 else -1
        else:
            # Could not recolor any vertex of max_color, so we cannot reduce further
            break

    return color

