def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        # Validate that entries are 0 or 1 (if not, treat as list)
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list from input
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj

    # Precompute degrees
    degrees = [len(adj_list[i]) for i in range(n)]

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get max color used
    def max_color_used(coloring):
        return max(coloring) if coloring else -1

    # DSATUR heuristic
    def dsatur():
        coloring = [-1] * n
        # saturation: list of sets of neighbor colors for each vertex
        saturation = [set() for _ in range(n)]
        # colored neighbor count for saturation degree
        colored_neighbors = [0] * n

        for _ in range(n):
            # Select uncolored vertex with max saturation degree, tie-break by degree
            max_sat = -1
            candidates = []
            for v in range(n):
                if coloring[v] == -1:
                    sat = len(saturation[v])
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [v]
                    elif sat == max_sat:
                        candidates.append(v)
            if not candidates:
                break  # should not happen
            # Tie-break by degree in original graph (or uncolored subgraph? use original for simplicity)
            v = max(candidates, key=lambda x: degrees[x])

            # Find smallest available color
            used = [False] * (n + 1)  # n colors enough
            for neighbor in adj_list[v]:
                if coloring[neighbor] != -1:
                    used[coloring[neighbor]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            coloring[v] = c

            # Update saturation of neighbors
            for neighbor in adj_list[v]:
                if coloring[neighbor] == -1:
                    saturation[neighbor].add(c)
        return coloring

    # Welsh-Powell ordering (largest degree first)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: degrees[x], reverse=True)
        coloring = [-1] * n
        for v in order:
            used = [False] * (n + 1)
            for neighbor in adj_list[v]:
                if coloring[neighbor] != -1:
                    used[coloring[neighbor]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            coloring[v] = c
        return coloring

    # Smallest-Last (degeneracy ordering)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        deg = degrees[:]
        order = []
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            if deg[v] < len(buckets):
                buckets[deg[v]].append(v)
            else:
                # extend buckets if needed
                while len(buckets) <= deg[v]:
                    buckets.append([])
                buckets[deg[v]].append(v)

        for _ in range(n):
            # Find first non-empty bucket from low to high
            v = -1
            for d in range(len(buckets)):
                while buckets[d]:
                    candidate = buckets[d].pop()
                    if candidate in remaining:
                        v = candidate
                        break
                if v != -1:
                    break
            if v == -1:
                # fallback: any remaining
                v = next(iter(remaining))
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for neighbor in adj_list[v]:
                if neighbor in remaining:
                    deg[neighbor] -= 1
                    old_d = deg[neighbor] + 1
                    new_d = deg[neighbor]
                    # move neighbor from old bucket to new bucket
                    if old_d < len(buckets) and v in buckets[old_d]:
                        pass  # we don't have v, but we need to remove neighbor from old bucket
                    # Instead, we rebuild buckets? Simpler: just add to new bucket and ignore old
                    # Since we are scanning buckets from low, we can just add to new bucket
                    if new_d < len(buckets):
                        buckets[new_d].append(neighbor)
                    else:
                        while len(buckets) <= new_d:
                            buckets.append([])
                        buckets[new_d].append(neighbor)
        # Color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)
            for neighbor in adj_list[v]:
                if coloring[neighbor] != -1:
                    used[coloring[neighbor]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            coloring[v] = c
        return coloring

    # RLF (Recursive Largest First) - independent set extraction
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build independent set for this color
            independent_set = []
            # Step 1: choose vertex with max degree in uncolored subgraph
            # Compute degrees in uncolored subgraph
            uncolored_deg = {}
            for v in uncolored:
                cnt = 0
                for neighbor in adj_list[v]:
                    if neighbor in uncolored:
                        cnt += 1
                uncolored_deg[v] = cnt
            if not uncolored_deg:
                break
            v = max(uncolored_deg, key=lambda x: uncolored_deg[x])
            independent_set.append(v)
            # Partition uncolored into U (not adjacent to S) and W (adjacent to S)
            S = set(independent_set)
            U = set()
            W = set()
            for u in uncolored:
                if u in S:
                    continue
                adjacent_to_S = False
                for s in S:
                    if u in adj_list[s] or s in adj_list[u]:  # undirected, so either way
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.add(u)
                else:
                    U.add(u)
            # While U not empty
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                for u in U:
                    w_neighbors = 0
                    for neighbor in adj_list[u]:
                        if neighbor in W:
                            w_neighbors += 1
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        # Tie-break: min degree in G[U]
                        deg_u = 0
                        for neighbor in adj_list[u]:
                            if neighbor in U:
                                deg_u += 1
                        if best_u == -1 or deg_u < best_deg_u:
                            best_u = u
                            best_deg_u = deg_u
                if best_u == -1:
                    break
                # Add best_u to S, remove from U, move its U-neighbors to W
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u that are in U to W
                for neighbor in adj_list[best_u]:
                    if neighbor in U:
                        U.remove(neighbor)
                        W.add(neighbor)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1
            # Next uncolored set is W
            uncolored = W
        return coloring

    # Kempe chain swap to reduce colors
    def kempe_reduce(coloring):
        k = max_color_used(coloring) + 1
        if k <= 1:
            return coloring
        # Try to eliminate color classes from highest down
        for target_color in range(k-1, 0, -1):
            # Get vertices with target_color
            verts = [v for v in range(n) if coloring[v] == target_color]
            if not verts:
                continue
            # Try to recolor each vertex to a lower color
            made_change = False
            for v in verts:
                # Try direct move to lower color
                neighbor_colors = set()
                for u in adj_list[v]:
                    if coloring[u] != -1:
                        neighbor_colors.add(coloring[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        coloring[v] = c
                        made_change = True
                        break
                if made_change:
                    break  # restart from highest color
                # Try Kempe chains
                for c in range(target_color):
                    # Check if v can be swapped via Kempe chain (target_color, c)
                    # We need to see if v is in a component that does not contain any vertex of color c that is adjacent to v? 
                    # Standard: consider the Kempe chain of v in colors {target_color, c}
                    # If the component of v does not contain any neighbor of v colored c, we can swap.
                    # Actually, we can swap if in the component, there is no vertex colored c that is adjacent to v? 
                    # Simpler: if we can swap the component of v without causing conflict.
                    # We'll do BFS for the component.
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    component = set()
                    while queue:
                        node = queue.popleft()
                        component.add(node)
                        for neighbor in adj_list[node]:
                            if neighbor not in visited and (coloring[neighbor] == target_color or coloring[neighbor] == c):
                                visited.add(neighbor)
                                queue.append(neighbor)
                    # Check if any neighbor of v in the component has color c? Actually, we need to see if swapping causes conflict.
                    # After swap, v becomes c. We need to ensure no neighbor of v is c after swap.
                    # Neighbors of v that are in the component and colored target_color will become c -> conflict if they are adjacent to v? 
                    # Actually, if a neighbor u of v is in the component and colored target_color, after swap u becomes c, and v becomes c -> same color on edge (v,u) -> conflict.
                    # So we can only swap if no neighbor of v is in the component? That is too restrictive.
                    # Correct condition: we can swap the component if it does not contain any vertex adjacent to v that is colored c? 
                    # Let me recall: In Kempe chain swap for vertex v from color a to b, we look at the (a,b)-component of v.
                    # If this component does not contain any neighbor of v colored b, then we can swap the component and v will become b without conflict.
                    # Because neighbors of v colored b are not in the component, so they stay b, and v becomes b -> but then edge (v, neighbor) would have both b? 
                    # Wait: if neighbor u of v is colored b and not in the component, then after swap, v becomes b and u remains b -> conflict.
                    # Actually, the condition is: the component of v must not contain any neighbor of v that is colored b? 
                    # I think the standard condition for removing color a is: for a vertex v of color a, if there exists a color b < a such that v is not adjacent to any vertex of color b in the (a,b)-component of v, then we can swap.
                    # More precisely: if in the (a,b)-component of v, there is no vertex colored b that is adjacent to v, then swapping the component will not cause v to conflict with its b-colored neighbors.
                    # Because after swap, v becomes b. Its neighbors that are colored b (and not in the component) remain b -> conflict? 
                    # Let's think: neighbor u of v colored b.
                    # Case 1: u in the (a,b)-component of v. Then after swap, u becomes a. So v becomes b, u becomes a -> different.
                    # Case 2: u not in the component. Then u stays b, v becomes b -> same color -> conflict.
                    # Therefore, we can swap only if there is no neighbor of v colored b that is outside the component? 
                    # Actually, we need that all neighbors of v colored b are inside the component? Then after swap, they become a, so no conflict.
                    # So condition: every neighbor of v colored b is in the (a,b)-component of v.
                    # Equivalent: no neighbor of v colored b is outside the component.
                    has_outside = False
                    for u in adj_list[v]:
                        if coloring[u] == c and u not in component:
                            has_outside = True
                            break
                    if not has_outside:
                        # Perform swap
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            elif coloring[node] == c:
                                coloring[node] = target_color
                        made_change = True
                        break
                if made_change:
                    break
            if not made_change:
                # Cannot reduce this color class, break
                break
        return coloring

    # Generate initial colorings from multiple heuristics
    candidates = []
    # DSATUR
    c1 = dsatur()
    if is_valid(c1):
        candidates.append(c1)
    # Welsh-Powell
    c2 = welsh_powell()
    if is_valid(c2):
        candidates.append(c2)
    # Smallest-Last
    c3 = smallest_last()
    if is_valid(c3):
        candidates.append(c3)
    # RLF
    c4 = rlf()
    if is_valid(c4):
        candidates.append(c4)

    # If no valid candidates (should not happen), fallback to greedy
    if not candidates:
        coloring = [-1] * n
        for v in range(n):
            used = [False] * (n + 1)
            for neighbor in adj_list[v]:
                if coloring[neighbor] != -1:
                    used[coloring[neighbor]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            coloring[v] = c
        candidates.append(coloring)

    # Select candidate with fewest colors
    best = min(candidates, key=lambda x: max_color_used(x) + 1)
    best_k = max_color_used(best) + 1

    # Apply Kempe reduction iteratively (limited iterations for speed)
    current = best[:]
    for _ in range(10):  # limit iterations
        reduced = kempe_reduce(current)
        new_k = max_color_used(reduced) + 1
        if new_k < best_k:
            current = reduced
            best_k = new_k
        else:
            break

    return current

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Determine if input is adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True
    # Build adjacency list and degree array
    neighbors = [[] for _ in range(n)]
    degree = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
        degree = [len(neighbors[i]) for i in range(n)]
    else:
        for i in range(n):
            neighbors[i] = list(adj[i])
        degree = [len(neighbors[i]) for i in range(n)]

    # Helper functions for coloring and validation
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    def is_valid_coloring(color):
        for u in range(n):
            cu = color[u]
            for v in neighbors[u]:
                if cu == color[v]:
                    return False
        return True

    # DSATUR implementation
    def dsatur():
        color = [-1] * n
        saturated = [set() for _ in range(n)]
        uncolored = set(range(n))
        # Initial vertex: highest degree
        if uncolored:
            v = max(uncolored, key=lambda x: degree[x])
            color[v] = 0
            saturated[v].add(0)
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    saturated[u].add(0)
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            v = max(uncolored, key=lambda x: (len(saturated[x]), 
                                             sum(1 for nb in neighbors[x] if nb in uncolored),
                                             random.random()))
            # Find smallest available color
            used = [False] * n
            for c in saturated[v]:
                used[c] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    saturated[u].add(c)
        return color

    # RLF implementation
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0
        while uncolored:
            # Build maximal independent set for current_color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for nb in neighbors[x] if nb in uncolored))
            independent_set = {v}
            # Partition remaining uncolored into U (not adjacent to S) and W (adjacent to S)
            U = uncolored - {v} - set(neighbors[v])
            W = set(nb for nb in neighbors[v] if nb in uncolored)
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U subgraph
                u = max(U, key=lambda x: (sum(1 for nb in neighbors[x] if nb in W),
                                          -sum(1 for nb in neighbors[x] if nb in U),
                                          random.random()))
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in neighbors[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to independent set
            for vertex in independent_set:
                color[vertex] = current_color
            uncolored -= independent_set
            current_color += 1
        return color

    # Smallest-Last ordering
    def smallest_last():
        if n == 0:
            return []
        # Compute core numbers via peeling
        deg = degree[:]
        order = []
        remaining = set(range(n))
        # Buckets for degrees
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            if deg[v] < len(buckets):
                buckets[deg[v]].append(v)
            else:
                # extend buckets if needed (should not happen as deg[v] <= n-1)
                while len(buckets) <= deg[v]:
                    buckets.append([])
                buckets[deg[v]].append(v)
        # Peeling
        for _ in range(n):
            # Find first non-empty bucket from low to high
            d = 0
            while d < len(buckets) and not buckets[d]:
                d += 1
            if d >= len(buckets):
                break  # should not happen
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    # remove u from its current bucket
                    old_deg = deg[u]
                    if old_deg < len(buckets) and u in buckets[old_deg]:
                        buckets[old_deg].remove(u)
                    deg[u] -= 1
                    new_deg = deg[u]
                    if new_deg < len(buckets):
                        buckets[new_deg].append(u)
                    else:
                        while len(buckets) <= new_deg:
                            buckets.append([])
                        buckets[new_deg].append(u)
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Welsh-Powell ordering
    def welsh_powell():
        order = sorted(range(n), key=lambda x: (-degree[x], x))
        return greedy_color(order)

    # Kempe chain swap for local search
    def kempe_swap(color, k):
        # Try to eliminate color k-1
        target = k - 1
        # Build color classes
        color_classes = [[] for _ in range(k)]
        for v in range(n):
            if color[v] < k:
                color_classes[color[v]].append(v)
        # If target color class is empty, already reduced
        if not color_classes[target]:
            return color, k - 1
        # Try to recolor each vertex in target class
        for v in color_classes[target]:
            # Try direct move to a lower color
            neighbor_colors = set()
            for u in neighbors[v]:
                if color[u] < k:
                    neighbor_colors.add(color[u])
            for c in range(target):
                if c not in neighbor_colors:
                    # Move v to color c
                    color[v] = c
                    color_classes[target].remove(v)
                    color_classes[c].append(v)
                    break
            else:
                # Direct move not possible, try Kempe chains
                for c in range(target):
                    # Check if v is in a Kempe chain of (target, c) that does not include any other vertex of color target
                    # We'll do BFS to get the component
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in neighbors[x]:
                            if not visited[y] and (color[y] == target or color[y] == c):
                                visited[y] = True
                                queue.append(y)
                    # Check if any other vertex in component has color target (besides v)
                    has_other_target = any(color[x] == target for x in component if x != v)
                    if not has_other_target:
                        # Swap colors in component
                        for x in component:
                            if color[x] == target:
                                color[x] = c
                            elif color[x] == c:
                                color[x] = target
                        # Update color classes
                        color_classes[target].remove(v)
                        color_classes[c].append(v)
                        break
                else:
                    continue
                break
        # Rebuild color array from classes (in case of changes)
        new_color = [-1] * n
        for c in range(k):
            for v in color_classes[c]:
                new_color[v] = c
        # Check if target color class is now empty
        if not any(v for v in range(n) if new_color[v] == target):
            return new_color, k - 1
        else:
            return new_color, k

    # Generate initial colorings
    initial_colorings = []
    # DSATUR
    initial_colorings.append(dsatur())
    # RLF
    initial_colorings.append(rlf())
    # Smallest-Last
    initial_colorings.append(smallest_last())
    # Welsh-Powell
    initial_colorings.append(welsh_powell())

    best_coloring = None
    best_k = float('inf')

    for color_init in initial_colorings:
        # Validate and compute k
        if not is_valid_coloring(color_init):
            continue
        k = max(color_init) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_coloring = color_init[:]
        # Apply Kempe chain local search to try to reduce k
        # We'll try a few iterations
        current_color = color_init[:]
        current_k = k
        improved = True
        # Limit iterations to avoid timeout
        for _ in range(10):  # max 10 Kempe reduction attempts
            if current_k <= 1:
                break
            new_color, new_k = kempe_swap(current_color, current_k)
            if new_k < current_k:
                current_color = new_color
                current_k = new_k
                improved = True
            else:
                # No improvement, break
                break
        if current_k < best_k:
            best_k = current_k
            best_coloring = current_color[:]

    # Fallback: if no valid coloring found (should not happen), use greedy on natural order
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = max(best_coloring) + 1 if n > 0 else 0

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []

    # Determine if input is adjacency matrix or list
    is_matrix = False
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n:
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Build adjacency list and degree list
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = [j for j in range(n) if adj[i][j] == 1]
            adj_list.append(neighbors)
    else:
        adj_list = adj

    deg = [len(neighbors) for neighbors in adj_list]

    # Helper functions for graph operations on subsets
    def degree_in_subset(v, subset_set):
        return sum(1 for u in adj_list[v] if u in subset_set)

    def sat_degree(v, colors, subset_set):
        neighbor_colors = set()
        for u in adj_list[v]:
            if u in subset_set and colors[u] != -1:
                neighbor_colors.add(colors[u])
        return len(neighbor_colors)

    # DSATUR algorithm
    def dsatur():
        colors = [-1] * n
        colored_set = set()

        for _ in range(n):
            # Select uncolored vertex with max saturation degree, tie-break by degree in uncolored subgraph, then random
            max_sat = -1
            candidates = []
            for v in range(n):
                if colors[v] == -1:
                    sat = sat_degree(v, colors, set(range(n)) - colored_set)
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [v]
                    elif sat == max_sat:
                        candidates.append(v)

            if not candidates:
                break  # Should not happen

            # Tie-break by degree in uncolored subgraph
            max_deg = -1
            final_candidates = []
            uncolored_set = set(range(n)) - colored_set
            for v in candidates:
                d = degree_in_subset(v, uncolored_set)
                if d > max_deg:
                    max_deg = d
                    final_candidates = [v]
                elif d == max_deg:
                    final_candidates.append(v)

            v = random.choice(final_candidates) if final_candidates else candidates[0]

            # Assign smallest available color
            used = [False] * (n + 1)
            for u in adj_list[v]:
                if colors[u] != -1:
                    used[colors[u]] = True
            for c in range(n + 1):
                if not used[c]:
                    colors[v] = c
                    break

            colored_set.add(v)

        return colors

    # RLF algorithm
    def rlf():
        colors = [-1] * n
        uncolored_set = set(range(n))
        color = 0

        while uncolored_set:
            # Build maximal independent set for current color
            S = []
            # Step 1: pick vertex with max degree in G[uncolored_set]
            if uncolored_set:
                v = max(uncolored_set, key=lambda x: degree_in_subset(x, uncolored_set))
                S.append(v)
                # U: vertices not adjacent to any in S (eligible)
                # W: vertices adjacent to at least one in S (ineligible for this color)
                W = set()
                for u in S:
                    for w in adj_list[u]:
                        if w in uncolored_set:
                            W.add(w)
                U = uncolored_set - set(S) - W
            else:
                U = set()

            # Step 2: while U not empty, add vertex with max neighbors in W
            while U:
                # Select u in U maximizing |N(u) ∩ W|, tie-break by min degree in G[U]
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in adj_list[u] if w in W)
                    deg_in_U = degree_in_subset(u, U)
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u

                if best_u is None:
                    break  # Should not happen

                S.append(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # Assign color to all in S
            for v in S:
                colors[v] = color

            # Next color class: uncolored vertices are now W (neighbors of S)
            uncolored_set = W
            color += 1

        return colors

    # Kempe chain refinement to reduce number of colors
    def kempe_refine(colors):
        # Get current number of colors
        max_color = max(colors) if n > 0 else -1
        if max_color < 0:
            return colors

        # Try to eliminate color classes from highest downwards
        for target_color in range(max_color, 0, -1):
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if colors[v] == target_color]
            if not target_vertices:
                continue  # This color already eliminated

            # Try to recolor each vertex in target_vertices to a lower color
            eliminated = True
            for v in target_vertices:
                # Check direct move to any lower color
                moved = False
                for c in range(target_color):
                    # Check if color c is available for v (no neighbor has color c)
                    conflict = False
                    for u in adj_list[v]:
                        if colors[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        colors[v] = c
                        moved = True
                        break

                if moved:
                    continue

                # Try Kempe chain swap for each lower color c
                swapped = False
                for c in range(target_color):
                    # If v already has color c after some swap, skip (shouldn't happen here)
                    if colors[v] == c:
                        swapped = True
                        break
                    # We consider swapping colors target_color and c
                    # Only if v is not of color c (it has target_color) and we look at the component
                    # Build the component of v in the subgraph induced by colors {target_color, c}
                    # But note: v has target_color, so we start from v
                    visited = set()
                    stack = [v]
                    visited.add(v)
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for nb in adj_list[node]:
                            if nb not in visited and (colors[nb] == target_color or colors[nb] == c):
                                visited.add(nb)
                                stack.append(nb)

                    # Check if any neighbor of v has color c (which would cause conflict after swap)
                    has_c_neighbor = False
                    for u in adj_list[v]:
                        if colors[u] == c:
                            has_c_neighbor = True
                            break

                    # If no neighbor has color c, we can swap the component
                    if not has_c_neighbor:
                        # Perform swap: target_color <-> c in the component
                        for node in component:
                            if colors[node] == target_color:
                                colors[node] = c
                            elif colors[node] == c:
                                colors[node] = target_color
                        swapped = True
                        break

                if not swapped:
                    eliminated = False
                    break  # Cannot eliminate this color class yet

            if eliminated:
                # Successfully eliminated target_color, continue to next lower color
                continue
