            v = -1
            max_sat = -1
            max_deg = -1
            for i in range(n):
                if not colored[i]:
                    if sat[i] > max_sat or (sat[i] == max_sat and deg_uncolored[i] > max_deg) or \
                       (sat[i] == max_sat and deg_uncolored[i] == max_deg and random.random() < 0.5):
                        max_sat = sat[i]
                        max_deg = deg_uncolored[i]
                        v = i
            if v == -1:
                break
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            colored[v] = True
            for u in neighbors[v]:
                if not colored[u]:
                    new_sat = True
                    for w in neighbors[u]:
                        if color[w] == c:
                            new_sat = False
                            break
                    if new_sat:
                        sat[u] += 1
                    deg_uncolored[u] -= 1
        return color

    col_ds = dsatur()
    k_ds = max(col_ds) + 1 if col_ds else 0
    if k_ds < best_k:
        best_k = k_ds
        best_color = col_ds

    # RLF (Recursive Largest First) heuristic with improved tie-breaking: min degree in U, then random
    def rlf():
        color = [-1] * n
        uncolored = [True] * n
        c = 0
        while any(uncolored):
            S = []
            deg_uncolored = [0] * n
            for i in range(n):
                if uncolored[i]:
                    for j in neighbors[i]:
                        if uncolored[j]:
                            deg_uncolored[i] += 1
            v = -1
            max_deg = -1
            for i in range(n):
                if uncolored[i] and deg_uncolored[i] > max_deg:
                    max_deg = deg_uncolored[i]
                    v = i
            if v == -1:
                break
            S.append(v)
            uncolored[v] = False
            U = [i for i in range(n) if uncolored[i]]
            W = set()
            for u in S:
                for w in neighbors[u]:
                    if uncolored[w]:
                        W.add(w)
            U = [i for i in U if i not in W]
            while U:
                deg_U = [0] * n
                for i in U:
                    for j in neighbors[i]:
                        if j in U:
                            deg_U[i] += 1
                best_u = -1
                max_w_neighbors = -1
                min_deg_U = n
                for u in U:
                    w_count = 0
                    for w in neighbors[u]:
                        if w in W:
                            w_count += 1
                    if w_count > max_w_neighbors or \
                       (w_count == max_w_neighbors and deg_U[u] < min_deg_U) or \
                       (w_count == max_w_neighbors and deg_U[u] == min_deg_U and random.random() < 0.5):
