            pos_in_bucket[v] = -1
            removed[v] = True
            order.append(v)
            for u in adj_set[v]:
                if not removed[u]:
                    d_u = curr_deg[u]
                    bucket_u = buckets[d_u]
                    pos_u = pos_in_bucket[u]
                    last_u = bucket_u[-1]
                    bucket_u[pos_u] = last_u
                    pos_in_bucket[last_u] = pos_u
                    bucket_u.pop()
                    curr_deg[u] -= 1
                    new_d = curr_deg[u]
                    buckets[new_d].append(u)
                    pos_in_bucket[u] = len(buckets[new_d]) - 1
                    if new_d < min_deg:
                        min_deg = new_d
