    def kempe_reduce(coloring):
        k = max(coloring) + 1 if coloring else 0
        if k <= 1:
            return coloring
        improved = True
        current = coloring[:]
        while improved and k > 1:
            improved = False
            last_color = k - 1
            vertices_last = [v for v in range(n) if current[v] == last_color]
            if not vertices_last:
                k -= 1
                continue
            for v in vertices_last:
                neighbor_colors = set(current[u] for u in neighbors[v])
                # Try direct recolor to a smaller color
                for c in range(last_color):
                    if c not in neighbor_colors:
                        current[v] = c
                        improved = True
                        break
                if improved:
                    if not any(current[u] == last_color for u in range(n)):
                        k -= 1
                    break
                # Try Kempe chain swap
                for c in range(last_color):
                    if c in neighbor_colors:
                        continue
                    stack = [v]
                    visited = set([v])
                    component = set()
                    while stack:
                        node = stack.pop()
                        component.add(node)
                        for u in neighbors[node]:
                            if current[u] in (last_color, c) and u not in visited:
                                visited.add(u)
                                stack.append(u)
                    has_conflict = False
                    for u in neighbors[v]:
                        if u in component:
                            if current[u] == last_color:
                                has_conflict = True
                                break
                        else:
                            if current[u] == c:
                                has_conflict = True
                                break
                    if not has_conflict:
                        for node in component:
                            if current[node] == last_color:
                                current[node] = c
                            elif current[node] == c:
                                current[node] = last_color
                        improved = True
                        break
                if improved:
                    break
            if not any(current[u] == last_color for u in range(n)):
                k -= 1
                improved = True
        return current

    final_color = kempe_reduce(best_color)
    if len(final_color) != n:
        final_color = best_color
    return final_color

