    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Welsh-Powell ordering (by initial degree descending)
    order_wp = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
    best_color = greedy_color(order_wp)
    best_k = max(best_color) + 1 if best_color else 0

    # DSATUR heuristic with refined tie-breaking: saturation degree, then degree in uncolored subgraph, then random
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        deg_uncolored = [len(neighbors[i]) for i in range(n)]
        colored = [False] * n
        for _ in range(n):
            v = -1
            max_sat = -1
            max_deg = -1
            for i in range(n):
                if not colored[i]:
                    if sat[i] > max_sat or \
                       (sat[i] == max_sat and deg_uncolored[i] > max_deg) or \
                       (sat[i] == max_sat and deg_uncolored[i] == max_deg and random.random() < 0.5):
                        max_sat = sat[i]
                        max_deg = deg_uncolored[i]
                        v = i
            if v == -1:
                break
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            colored[v] = True
            for u in neighbors[v]:
                if not colored[u]:
                    new_sat = True
                    for w in neighbors[u]:
                        if color[w] == c:
                            new_sat = False
                            break
                    if new_sat:
                        sat[u] += 1
                    deg_uncolored[u] -= 1
        return color

    col_ds = dsatur()
    k_ds = max(col_ds) + 1 if col_ds else 0
    if k_ds < best_k:
        best_k = k_ds
        best_color = col_ds

    # RLF (Recursive Largest First) heuristic with independent set extraction and refined tie-breaking
    def rlf():
        color = [-1] * n
        uncolored = [True] * n
        c = 0
        while any(uncolored):
            S = []
            deg_uncolored = [0] * n
            for i in range(n):
                if uncolored[i]:
                    for j in neighbors[i]:
                        if uncolored[j]:
                            deg_uncolored[i] += 1
            v = -1
            max_deg = -1
            for i in range(n):
                if uncolored[i] and deg_uncolored[i] > max_deg:
                    max_deg = deg_uncolored[i]
                    v = i
            if v == -1:
                break
            S.append(v)
            uncolored[v] = False
            U = [i for i in range(n) if uncolored[i]]
            W = set()
            for u in S:
                for w in neighbors[u]:
                    if uncolored[w]:
                        W.add(w)
            U = [i for i in U if i not in W]
            while U:
                deg_U = [0] * n
                for i in U:
                    for j in neighbors[i]:
                        if j in U:
                            deg_U[i] += 1
                best_u = -1
                max_w_neighbors = -1
                min_deg_U = n
                for u in U:
                    w_count = 0
                    for w in neighbors[u]:
                        if w in W:
                            w_count += 1
                    if w_count > max_w_neighbors or \
                       (w_count == max_w_neighbors and deg_U[u] < min_deg_U) or \
                       (w_count == max_w_neighbors and deg_U[u] == min_deg_U and random.random() < 0.5):
                        max_w_neighbors = w_count
                        min_deg_U = deg_U[u]
                        best_u = u
                if best_u == -1:
                    break
                S.append(best_u)
                uncolored[best_u] = False
                U.remove(best_u)
                for w in neighbors[best_u]:
                    if uncolored[w] and w not in W:
                        W.add(w)
                U = [i for i in U if i not in W]
            for v in S:
                color[v] = c
            c += 1
        return color

    col_rlf = rlf()
    k_rlf = max(col_rlf) + 1 if col_rlf else 0
    if k_rlf < best_k:
        best_k = k_rlf
        best_color = col_rlf

    # Smallest-Last (SL) ordering heuristic with efficient bucket queue
    def smallest_last():
        if n == 0:
            return []
        degree = [len(neighbors[i]) for i in range(n)]
        adj_set = [set(neighbors[i]) for i in range(n)]
        max_deg = n - 1
        buckets = [[] for _ in range(max_deg + 1)]
        pos_in_bucket = [0] * n
        curr_deg = degree[:]
        for i in range(n):
            d = curr_deg[i]
            buckets[d].append(i)
            pos_in_bucket[i] = len(buckets[d]) - 1
        removed = [False] * n
        order = []
        min_deg = 0
        for _ in range(n):
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break
            v = buckets[min_deg].pop()
            pos_in_bucket[v] = -1
            removed[v] = True
            order.append(v)
            for u in adj_set[v]:
                if not removed[u]:
                    d_u = curr_deg[u]
                    bucket_u = buckets[d_u]
                    pos_u = pos_in_bucket[u]
                    last_u = bucket_u[-1]
                    bucket_u[pos_u] = last_u
                    pos_in_bucket[last_u] = pos_u
                    bucket_u.pop()
                    curr_deg[u] -= 1
                    new_d = curr_deg[u]
                    buckets[new_d].append(u)
                    pos_in_bucket[u] = len(buckets[new_d]) - 1
                    if new_d < min_deg:
                        min_deg = new_d
        color = [-1] * n
        for v in reversed(order):
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    col_sl = smallest_last()
    k_sl = max(col_sl) + 1 if col_sl else 0
    if k_sl < best_k:
        best_k = k_sl
        best_color = col_sl

    # Kempe chain local search to reduce colors with refined tie-breaking
    def kempe_reduce(coloring):
        k = max(coloring) + 1 if coloring else 0
        if k <= 1:
            return coloring
        improved = True
        current = coloring[:]
        while improved and k > 1:
            improved = False
            last_color = k - 1
            vertices_last = [v for v in range(n) if current[v] == last_color]
            if not vertices_last:
                k -= 1
                continue
            for v in vertices_last:
                neighbor_colors = set(current[u] for u in neighbors[v])
                # Try direct recolor to a smaller color
                for c in range(last_color):
                    if c not in neighbor_colors:
                        current[v] = c
                        improved = True
                        break
                if improved:
                    if not any(current[u] == last_color for u in range(n)):
                        k -= 1
                    break
                # Try Kempe chain swap
                for c in range(last_color):
                    if c in neighbor_colors:
                        continue
                    stack = [v]
                    visited = set([v])
                    component = set()
                    while stack:
                        node = stack.pop()
                        component.add(node)
                        for u in neighbors[node]:
                            if current[u] in (last_color, c) and u not in visited:
                                visited.add(u)
                                stack.append(u)
                    has_conflict = False
                    for u in neighbors[v]:
                        if u in component:
                            if current[u] == last_color:
                                has_conflict = True
                                break
                        else:
                            if current[u] == c:
                                has_conflict = True
                                break
                    if not has_conflict:
                        for node in component:
                            if current[node] == last_color:
                                current[node] = c
                            elif current[node] == c:
                                current[node] = last_color
                        improved = True
                        break
                if improved:
                    break
            if not any(current[u] == last_color for u in range(n)):
                k -= 1
                improved = True
        return current

    final_color = kempe_reduce(best_color)
    if len(final_color) != n:
        final_color = best_color
    return final_color
